const uid = (ctx.user && ctx.user.id) || (ctx.session && ctx.session.userId);
if (!uid) throw new Error('Sign in to file a claim.');
const tripId = input.trip && typeof input.trip === 'object' ? input.trip.id : input.trip;
const trip = tripId ? await ctx.api.object('demotravel_trip_request').findOne({ where: { id: tripId } }) : null;
if (!trip) throw new Error('Trip request not found.');
if (trip.status !== 'approved') throw new Error('A claim can only be filed against an approved trip request.');
const me = await ctx.api.object('demotravel_employee').findOne({ where: { user: uid } });
if (!me || me.id !== trip.traveler) throw new Error('You can only file a claim for your own trip.');
let lines = input.lines;
if (typeof lines === 'string') lines = JSON.parse(lines || '[]');
if (!Array.isArray(lines) || lines.length === 0) throw new Error('Give at least one expense line.');
const today = new Date().toISOString().slice(0, 10);
const count = await ctx.api.object('demotravel_expense_claim').count({});
const name = 'EC-' + String(count + 1).padStart(4, '0') + '-' + String(Date.now()).slice(-5);
let created = null;
await ctx.api.transaction(async () => {
  created = await ctx.api.object('demotravel_expense_claim').insert({
    name: name,
    claimant: me.id,
    trip: trip.id,
    claim_date: input.claim_date || today,
    status: 'draft',
  });
  for (const l of lines) {
    await ctx.api.object('demotravel_claim_line').insert({
      claim: created.id,
      expense_type: l.expense_type,
      expense_date: l.expense_date || trip.start_date,
      quantity: l.quantity == null ? 1 : Number(l.quantity),
      unit_amount: Number(l.unit_amount),
      over_reason: l.over_reason || null,
    });
  }
});
return { claim_id: created.id, name: name };

