const prev = ctx.previous || {};
const input = ctx.input || {};
const has = (k) => Object.prototype.hasOwnProperty.call(input, k);
const claimId = has('claim') ? input.claim : prev.claim;
const expenseType = has('expense_type') ? input.expense_type : prev.expense_type;
const unitRaw = has('unit_amount') ? input.unit_amount : prev.unit_amount;
const reason = has('over_reason') ? input.over_reason : prev.over_reason;
let over = false;
if (claimId && expenseType && unitRaw !== null && unitRaw !== undefined && unitRaw !== '') {
  const unit = Number(unitRaw);
  const claim = await ctx.api.object('demotravel_expense_claim').findOne({ where: { id: claimId } });
  const claimantId = claim && claim.claimant && typeof claim.claimant === 'object' ? claim.claimant.id : (claim ? claim.claimant : null);
  if (claimantId) {
    const emp = await ctx.api.object('demotravel_employee').findOne({ where: { id: claimantId } });
    if (emp && emp.grade) {
      const std = await ctx.api.object('demotravel_travel_standard').findOne({ where: { grade: emp.grade, expense_type: expenseType } });
      if (std && std.cap_amount !== null && std.cap_amount !== undefined && !Number.isNaN(unit)) {
        over = unit > Number(std.cap_amount);
      }
    }
  }
}
ctx.input.over_standard = over;
if (over && (reason === null || reason === undefined || String(reason).trim() === '')) {
  throw new Error('This line is above the travel standard for the claimant\'s grade: give a reason (over_reason) before saving.');
}
